import sys

def solve_case(n, s, zones):
    # 按左端点排序
    zones.sort()
    cur_l, cur_r = zones[0]
    for i in range(1, n):
        L, R = zones[i]
        # 若当前区间与合并区间相交或相邻，则扩展合并区间
        if L <= cur_r + 1:
            cur_r = max(cur_r, R)
        else:
            # 检查 s 是否在当前合并的区间内
            if cur_l <= s <= cur_r:
                return min(s - cur_l + 1, cur_r - s + 1)
            cur_l, cur_r = L, R
    # 检查最后一个合并区间
    if cur_l <= s <= cur_r:
        return min(s - cur_l + 1, cur_r - s + 1)
    return 0

def main():
    input = sys.stdin.readline
    T = int(input().strip())
    ans = []
    for _ in range(T):
        n, s = map(int, input().split())
        zones = [tuple(map(int, input().split())) for _ in range(n)]
        ans.append(str(solve_case(n, s, zones)))
    print("\n".join(ans))

if __name__ == "__main__":
    main()
